import{A as e,H as t,P as n,_ as r,a as i,f as a,g as o,h as s,l as c,t as l,u}from"./chunks/plugin-vue_export-helper.I53torQa.js";var d=JSON.parse(`{"title":"昇腾硬件架构：达芬奇架构、910C/A3 与 950","description":"从达芬奇计算架构出发，梳理 Ascend 910C、Atlas A3 与 Ascend 950 的芯片、服务器和超节点层级，并补充 910C-128 超节点实机核验、CANN 软件栈及部署验证方法。","frontmatter":{"title":"昇腾硬件架构：达芬奇架构、910C/A3 与 950","description":"从达芬奇计算架构出发，梳理 Ascend 910C、Atlas A3 与 Ascend 950 的芯片、服务器和超节点层级，并补充 910C-128 超节点实机核验、CANN 软件栈及部署验证方法。"},"headers":[],"relativePath":"ascend/architecture/ascend-hardware-architecture.md","filePath":"ascend/architecture/ascend-hardware-architecture.md","lastUpdated":1795483478000}`),f={name:`ascend/architecture/ascend-hardware-architecture.md`};function p(l,d,f,p,m,h){let g=n(`Mermaid`);return e(),a(`div`,null,[d[12]||=s(`<h1 id="昇腾硬件架构-达芬奇架构、910c-a3-与-950" tabindex="-1">昇腾硬件架构：达芬奇架构、910C/A3 与 950 <a class="header-anchor" href="#昇腾硬件架构-达芬奇架构、910c-a3-与-950" aria-label="Permalink to “昇腾硬件架构：达芬奇架构、910C/A3 与 950”">​</a></h1><p>本文先介绍达芬奇架构的计算、存储和数据流，再分析 Ascend 910C 与 Atlas A3、910C-128 超节点的现场配置，最后讨论 Ascend 950。CANN 软件栈、部署检查和性能验证方法列在附录。</p><p>参数分为官方产品规格、CloudMatrix384 论文配置和现场采样三类，正文分别标注。比较时应先确认芯片、Die、加速卡、服务器或超节点层级，再核对数据格式、带宽方向及理论或实测口径。</p><h2 id="_1-达芬奇架构-计算、存储与数据流" tabindex="-1">1. 达芬奇架构：计算、存储与数据流 <a class="header-anchor" href="#_1-达芬奇架构-计算、存储与数据流" aria-label="Permalink to “1. 达芬奇架构：计算、存储与数据流”">​</a></h2><h3 id="_1-1-host-与-device-的分工" tabindex="-1">1.1 Host 与 Device 的分工 <a class="header-anchor" href="#_1-1-host-与-device-的分工" aria-label="Permalink to “1.1 Host 与 Device 的分工”">​</a></h3><p>昇腾程序通常由 Host CPU 和 Device NPU 协同执行。Host 侧运行应用、框架和 CANN Runtime，负责设备管理、内存分配、任务提交及运行时控制；Device 侧执行 Kernel，完成矩阵、向量和数据搬运等操作。[1][2]</p>`,6),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-18`,class:`mermaid`,graph:`flowchart%20LR%0A%20%20subgraph%20host%5B%22Host%20%E4%BE%A7%22%5D%0A%20%20%20%20cpu%5B%22Host%20CPU%22%5D%0A%20%20%20%20ddr%5B%22Host%20%E5%86%85%E5%AD%98%22%5D%0A%20%20%20%20runtime%5B%22%E6%A1%86%E6%9E%B6%20%2F%20CANN%20Runtime%3Cbr%2F%3E%E8%AE%BE%E5%A4%87%E3%80%81%E5%86%85%E5%AD%98%E4%B8%8E%20Stream%20%E7%AE%A1%E7%90%86%22%5D%0A%20%20%20%20cpu%20--%3E%20runtime%0A%20%20%20%20runtime%20--%3E%20ddr%0A%20%20end%0A%20%20subgraph%20device%5B%22Device%20%E4%BE%A7%EF%BC%9A%E6%98%87%E8%85%BE%20NPU%22%5D%0A%20%20%20%20scheduler%5B%22%E4%BB%BB%E5%8A%A1%E8%B0%83%E5%BA%A6%22%5D%0A%20%20%20%20cores%5B%22AI%20Core%20%2F%20AI%20CPU%20%2F%20%E5%85%B6%E4%BB%96%E5%8A%A0%E9%80%9F%E5%99%A8%22%5D%0A%20%20%20%20gm%5B%22Device%20%E5%85%A8%E5%B1%80%E5%86%85%E5%AD%98%20GM%22%5D%0A%20%20%20%20scheduler%20--%3E%20cores%0A%20%20%20%20cores%20%3C--%3E%20gm%0A%20%20end%0A%20%20runtime%20--%3E%7C%22Kernel%20%E4%B8%8E%E4%BB%BB%E5%8A%A1%E4%B8%8B%E5%8F%91%22%7C%20scheduler%0A%20%20ddr%20%3C--%3E%7C%22%E8%BE%93%E5%85%A5%E3%80%81%E8%BE%93%E5%87%BA%E6%95%B0%E6%8D%AE%E4%BC%A0%E8%BE%93%22%7C%20gm%0A`})]),fallback:t(()=>[...d[0]||=[o(` Loading... `,-1)]]),_:1})),d[13]||=s(`<p>Host 与 Device 通常拥有各自的内存空间。常规路径下，Host 数据需要通过运行时或框架提供的接口传入 Device；Host 指针不能因为数值相同就被当作 Device 指针使用。部分平台支持统一编址或共享访存，但地址映射、访问权限、同步和一致性规则仍由具体平台及软件接口决定。</p><h3 id="_1-2-ai-core-cube、vector-与-scalar" tabindex="-1">1.2 AI Core：Cube、Vector 与 Scalar <a class="header-anchor" href="#_1-2-ai-core-cube、vector-与-scalar" aria-label="Permalink to “1.2 AI Core：Cube、Vector 与 Scalar”">​</a></h3><p>AI Core 是执行 AI Kernel 的主要计算资源。Ascend C 将其抽象为 Cube、Vector、Scalar 三类计算单元，以及内部存储、数据搬运和控制单元。[1][2]</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>单元</th><th>主要职责</th><th>常见工作</th></tr></thead><tbody><tr><td>Cube</td><td>矩阵乘加和张量计算</td><td>GEMM、卷积的矩阵化计算、注意力中的 <code>QKᵀ</code> 与 <code>PV</code></td></tr><tr><td>Vector</td><td>对一组数据执行向量运算</td><td>逐元素运算、归约、Softmax、GELU、量化和反量化</td></tr><tr><td>Scalar</td><td>标量运算、地址计算、流程控制和指令发射</td><td>循环、分支、参数准备和流水控制</td></tr></tbody></table></div><p>Cube 的左右输入矩阵分别进入 L0A、L0B，计算结果及中间累加值写入 L0C。Vector 的输入、输出和中间数据通常放在 Unified Buffer（UB）中。Scalar 负责控制与调度，不宜承担大规模通用数据计算；若 Kernel 中存在大量标量操作或复杂分支，可能影响计算流水效率。</p><h4 id="耦合模式与分离模式" tabindex="-1">耦合模式与分离模式 <a class="header-anchor" href="#耦合模式与分离模式" aria-label="Permalink to “耦合模式与分离模式”">​</a></h4><p>Cube、Vector 是否部署在同一个核内，决定了 AI Core 的两种组织方式。[1]</p><ul><li><strong>耦合模式</strong>：Cube 和 Vector 共用一个 Scalar 调度单元，部署在同一个 AI Core 内。</li><li><strong>分离模式</strong>：Cube Core 和 Vector Core 各自拥有 Scalar 调度单元。两者按硬件设定的比例组合成逻辑 AI Core；该模式下，AI Core 数量按 Cube Core 数量统计。</li></ul>`,8),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-99`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20subgraph%20coupled%5B%22%E8%80%A6%E5%90%88%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20%20%20s1%5B%22%E5%85%B1%E4%BA%AB%20Scalar%20%E8%B0%83%E5%BA%A6%22%5D%0A%20%20%20%20c1%5B%22Cube%20%E7%9F%A9%E9%98%B5%E8%AE%A1%E7%AE%97%22%5D%0A%20%20%20%20v1%5B%22Vector%20%E5%90%91%E9%87%8F%E8%AE%A1%E7%AE%97%22%5D%0A%20%20%20%20s1%20--%3E%20c1%0A%20%20%20%20s1%20--%3E%20v1%0A%20%20end%0A%20%20subgraph%20separated%5B%22%E5%88%86%E7%A6%BB%E6%A8%A1%E5%BC%8F%EF%BC%9A1%20Cube%20Core%20%2B%20N%20Vector%20Core%22%5D%0A%20%20%20%20s2%5B%22Cube%20Core%20%E7%9A%84%20Scalar%22%5D%0A%20%20%20%20s3%5B%22Vector%20Core%20%E7%9A%84%20Scalar%22%5D%0A%20%20%20%20c2%5B%22Cube%20Core%20%2F%20AIC%22%5D%0A%20%20%20%20v2%5B%22Vector%20Core%20%2F%20AIV%22%5D%0A%20%20%20%20s2%20--%3E%20c2%0A%20%20%20%20s3%20--%3E%20v2%0A%20%20%20%20c2%20~~~%20v2%0A%20%20end%0A`})]),fallback:t(()=>[...d[1]||=[o(` Loading... `,-1)]]),_:1})),d[14]||=s(`<p>分离模式下，AIC 通常指 Cube Core，AIV 指 Vector Core。昇腾社区当前 Ascend C 文档列出的产品模式包括：Atlas A2/A3 训练和推理系列采用分离模式；Atlas 350 采用分离模式；较早的 Atlas 训练、推理系列采用耦合模式。Atlas 200I/500 A2 的硬件支持两种模式，但 Ascend C 编程场景使用耦合模式。具体核数、AIC/AIV 配比及接口支持情况，应以目标设备的硬件信息和对应 CANN 版本文档为准。[1][2]</p><p>NPU 还可能集成 AI CPU。AI CPU 位于 Device 侧，承担部分控制、标量、通用 CPU 算子及调度相关工作；Host CPU 运行主机操作系统、应用和主机侧软件栈。两者的职责不能混为一谈。[3]</p><h3 id="_1-3-存储层次" tabindex="-1">1.3 存储层次 <a class="header-anchor" href="#_1-3-存储层次" aria-label="Permalink to “1.3 存储层次”">​</a></h3><p>昇腾的存储体系不是一条所有数据都必须依次经过的缓存链。硬件管理的 Cache、软件显式规划的 Local Memory，以及 Device 全局内存，各自承担不同任务。</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>存储</th><th>主要作用</th><th>使用时需要注意</th></tr></thead><tbody><tr><td>GM（Global Memory）</td><td>算子编程中的设备全局内存视角，保存 Kernel 输入、输出及中间数据</td><td>GM 是软件层的逻辑视角；物理介质通常是 HBM 或其他设备内存，不能把 GM 与某一种物理内存直接画等号</td></tr><tr><td>L2 Cache</td><td>服务设备全局访存的共享缓存，可缓存代码和数据</td><td>主要由硬件管理，不等同于软件显式分配的 L1、L0 或 UB</td></tr><tr><td>L1 Buffer</td><td>AI Core 内部的局部存储，为矩阵计算暂存和复用数据</td><td>不是 Vector 专用缓存；具体容量、连接和用途随架构而变</td></tr><tr><td>L0A / L0B</td><td>保存 Cube 的左右输入矩阵</td><td>数据排布、分块和对齐需要满足 Cube 通路要求</td></tr><tr><td>L0C</td><td>保存 Cube 计算结果及中间累加结果</td><td>输出可经 FixPipe 等路径处理后写入支持的目标存储</td></tr><tr><td>UB（Unified Buffer）</td><td>Vector/Scalar 运算的输入、输出和中间数据存储</td><td>属于 AI Core 内部 Local Memory，不宜简单类比为 GPU 寄存器</td></tr><tr><td>BiasTable / Fixpipe Buffer 等</td><td>为偏置、量化和结果处理等专用路径提供存储</td><td>是否具备及容量取决于具体产品架构</td></tr></tbody></table></div><p>GM、L2 和 AI Core 内部 Local Memory 的角色不同。优化算子时，通常需要把频繁复用的数据留在片上局部存储，减少不必要的 GM 读写；但分块大小必须服从目标平台的存储容量、数据排布和访问粒度。</p><h3 id="_1-4-数据搬运-mte-与-fixpipe" tabindex="-1">1.4 数据搬运：MTE 与 FixPipe <a class="header-anchor" href="#_1-4-数据搬运-mte-与-fixpipe" aria-label="Permalink to “1.4 数据搬运：MTE 与 FixPipe”">​</a></h3><p>MTE（Memory Transfer Engine）负责不同存储空间之间的数据搬运；部分路径支持在搬运过程中完成数据格式或数值类型转换。常见路径如下。[1][2]</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>单元</th><th>常见路径</th><th>说明</th></tr></thead><tbody><tr><td>MTE2</td><td>GM → L1、GM → UB；部分架构也支持 GM → L0A/L0B</td><td>从全局内存向 AI Core 内部存储搬入数据</td></tr><tr><td>MTE1</td><td>L1 → L0A/L0B；部分架构还涉及 BiasTable Buffer</td><td>为 Cube 准备矩阵输入</td></tr><tr><td>MTE3</td><td>UB → GM</td><td>将 Vector 路径的结果写回全局内存</td></tr><tr><td>FixPipe</td><td>L0C → GM/L1；部分架构支持随路格式转换</td><td>处理 Cube 结果及量化、排布转换等操作</td></tr></tbody></table></div>`,9),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-276`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20subgraph%20vector_path%5B%22Vector%20%E6%95%B0%E6%8D%AE%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20direction%20LR%0A%20%20%20%20gm1%5B%22GM%22%5D%20--%3E%7C%22MTE2%22%7C%20ub1%5B%22UB%22%5D%0A%20%20%20%20ub1%20--%3E%20vec%5B%22Vector%22%5D%0A%20%20%20%20vec%20--%3E%20ub2%5B%22UB%22%5D%0A%20%20%20%20ub2%20--%3E%7C%22MTE3%22%7C%20gm2%5B%22GM%22%5D%0A%20%20end%0A%20%20subgraph%20cube_path%5B%22Cube%20%E6%95%B0%E6%8D%AE%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20direction%20LR%0A%20%20%20%20gm3%5B%22GM%22%5D%20--%3E%7C%22MTE2%22%7C%20l1%5B%22L1%20Buffer%22%5D%0A%20%20%20%20l1%20--%3E%7C%22MTE1%22%7C%20l0ab%5B%22L0A%20%2F%20L0B%22%5D%0A%20%20%20%20l0ab%20--%3E%20cube%5B%22Cube%22%5D%0A%20%20%20%20cube%20--%3E%20l0c%5B%22L0C%22%5D%0A%20%20%20%20l0c%20--%3E%20fix%5B%22FixPipe%22%5D%0A%20%20%20%20fix%20--%3E%20gm4%5B%22GM%20%E6%88%96%20L1%22%5D%0A%20%20end%0A`})]),fallback:t(()=>[...d[2]||=[o(` Loading... `,-1)]]),_:1})),d[15]||=s(`<p>图中展示的是典型数据流，不代表每个 MTE 只能访问固定的一对地址空间。不同芯片的存储大小、访问粒度和搬运路径可能不同，应查询目标产品的架构文档或通过开发接口获取实际容量。[1]</p><p>算子优化中的 Tiling、数据复用、对齐和双缓冲，都是围绕局部存储与搬运通路展开的。分块过大可能挤占 UB/L1 等资源；分块过小则可能增加搬运、调度和同步开销。</p><h3 id="_1-5-指令队列与同步" tabindex="-1">1.5 指令队列与同步 <a class="header-anchor" href="#_1-5-指令队列与同步" aria-label="Permalink to “1.5 指令队列与同步”">​</a></h3><p>Host 提交 Kernel 后，运行时创建并管理 Device Task 和 Stream。Device 调度单元再将任务分配给可用计算资源。一个 Kernel 通常由多个 AI Core 处理不同的数据分块，形成 SPMD（Single Program, Multiple Data）式并行执行。[2]</p><p>在 AI Core 内部，Scalar 发射指令：标量指令直接执行，Vector、Cube 和 MTE 指令进入相应执行流水或队列。不同流水可以并行工作，但指令被发射或进入队列，并不代表其数据读写已经完成。</p><p>Ascend C 常用以下机制表达流水依赖：[1]</p><ul><li><code>PipeBarrier</code>：约束相关流水的先后关系，使后续操作不会越过需要等待的前序操作。</li><li><code>SetFlag</code> / <code>WaitFlag</code>：在不同流水或任务之间建立事件依赖；前一侧完成约定操作后设置标志，等待方在标志满足前不能继续执行依赖操作。</li></ul><p>例如 <code>GM → UB → Vector → UB → GM</code> 这一流程中，数据搬入完成后才能进行计算，计算完成后才能搬出。若循环复用同一块 UB，还要确保新数据不会覆盖尚未被消费的旧数据。Ascend C 的高层编程范式可以处理常见同步关系；手动同步应建立在明确理解目标流水与缓冲区生命周期的基础上。</p><h3 id="_1-6-以-flashattention-观察计算与搬运的配合" tabindex="-1">1.6 以 FlashAttention 观察计算与搬运的配合 <a class="header-anchor" href="#_1-6-以-flashattention-观察计算与搬运的配合" aria-label="Permalink to “1.6 以 FlashAttention 观察计算与搬运的配合”">​</a></h3><p>注意力计算同时包含矩阵乘、非线性处理和大量数据移动，可以用来理解 Cube、Vector 与 MTE 的协作。</p>`,10),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-316`,class:`mermaid`,graph:`flowchart%20LR%0A%20%20qkv%5B%22%E4%BB%8E%20GM%20%E5%88%86%E5%9D%97%E8%AF%BB%E5%8F%96%20Q%E3%80%81K%E3%80%81V%22%5D%20--%3E%20qk%5B%22Cube%EF%BC%9A%E8%AE%A1%E7%AE%97%20QK%E1%B5%80%22%5D%0A%20%20qk%20--%3E%20softmax%5B%22Vector%EF%BC%9A%E7%BC%A9%E6%94%BE%E3%80%81Softmax%20%E4%B8%8E%E5%BD%92%E4%B8%80%E5%8C%96%22%5D%0A%20%20softmax%20--%3E%20pv%5B%22Cube%EF%BC%9A%E8%AE%A1%E7%AE%97%E6%A6%82%E7%8E%87%E7%9F%A9%E9%98%B5%E4%B8%8E%20V%20%E7%9A%84%E4%B9%98%E7%A7%AF%22%5D%0A%20%20pv%20--%3E%20out%5B%22%E7%BB%93%E6%9E%9C%E5%A4%84%E7%90%86%E5%B9%B6%E5%86%99%E5%9B%9E%20GM%22%5D%0A`})]),fallback:t(()=>[...d[3]||=[o(` Loading... `,-1)]]),_:1})),d[16]||=s(`<p>实际 FlashAttention 实现还要维护在线 Softmax 的归一化状态，并对 Head、序列长度和矩阵维度进行分块。图中是逻辑阶段，不代表每一步都要把完整注意力矩阵写回 GM。优化目标是让中间数据尽可能在局部存储中复用，同时利用异步搬运和双缓冲，使数据准备与计算重叠。</p><hr><h2 id="_2-ascend-910c-与-atlas-a3-从芯片到超节点" tabindex="-1">2. Ascend 910C 与 Atlas A3：从芯片到超节点 <a class="header-anchor" href="#_2-ascend-910c-与-atlas-a3-从芯片到超节点" aria-label="Permalink to “2. Ascend 910C 与 Atlas A3：从芯片到超节点”">​</a></h2><h3 id="_2-1-先区分产品层级" tabindex="-1">2.1 先区分产品层级 <a class="header-anchor" href="#_2-1-先区分产品层级" aria-label="Permalink to “2.1 先区分产品层级”">​</a></h3><p>“Ascend 910C”“Atlas 800T A3”“一张 NPU 卡”和“一个训练 rank”不是同一层级。芯片、加速模块、服务器、超节点和软件可见设备之间存在映射关系，不能只凭商品名称推断计算 Die 数、Runtime device 数或 rank 数。</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>层级</th><th>示例</th><th>核对重点</th></tr></thead><tbody><tr><td>AI 处理器</td><td>Ascend 310、910B、910C、950PR、950DT</td><td>架构代际、计算核心、内存和 I/O 能力</td></tr><tr><td>SoC 型号</td><td>设备查询得到的 <code>soc_version</code></td><td>离线编译目标、算子支持和平台差异</td></tr><tr><td>加速卡/计算模组</td><td>Atlas 350 等</td><td>模组数量、设备内存、功耗、接口和散热</td></tr><tr><td>服务器/计算节点</td><td>Atlas 800T A3、Atlas 800I A3</td><td>NPU/CPU 数量、Host 内存、PCIe 与网络拓扑</td></tr><tr><td>超节点</td><td>Atlas 900 A3、Atlas 950 SuperPoD</td><td>节点规模、交换拓扑、寻址范围和故障域</td></tr><tr><td>云服务实例</td><td>CloudMatrix384 等</td><td>底层硬件配置、资源池切分和云服务接口</td></tr><tr><td>软件可见设备</td><td>Runtime 枚举出的 Device</td><td>物理封装、计算 Die 与逻辑设备的映射</td></tr><tr><td>分布式训练单元</td><td>rank、通信组</td><td>rank 与 Device 的绑定及通信算法</td></tr></tbody></table></div>`,6),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-435`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20chip%5B%22AI%20%E5%A4%84%E7%90%86%E5%99%A8%20%2F%20NPU%22%5D%20--%3E%20module%5B%22%E5%8A%A0%E9%80%9F%E5%8D%A1%E6%88%96%E8%AE%A1%E7%AE%97%E6%A8%A1%E7%BB%84%22%5D%0A%20%20module%20--%3E%20node%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%20%2F%20%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%22%5D%0A%20%20node%20--%3E%20pod%5B%22%E8%B6%85%E8%8A%82%E7%82%B9%20SuperPoD%22%5D%0A%20%20pod%20--%3E%20cluster%5B%22%E6%99%BA%E7%AE%97%E9%9B%86%E7%BE%A4%20%2F%20%E4%BA%91%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20host%5B%22Host%20CPU%E3%80%81DDR%E3%80%81%E5%AD%98%E5%82%A8%E5%92%8C%E7%BD%91%E5%8D%A1%22%5D%20--%3E%20node%0A%20%20node_link%5B%22%E8%8A%82%E7%82%B9%E5%86%85%EF%BC%9ASIO%20%2F%20HCCS%22%5D%20---%20node%0A%20%20pod_link%5B%22Scale-Up%EF%BC%9A%E7%81%B5%E8%A1%A2%20UB%22%5D%20---%20pod%0A%20%20cluster_link%5B%22Scale-Out%EF%BC%9ARoCE%20%2F%20UBoE%22%5D%20---%20cluster%0A%20%20software%5B%22CANN%E3%80%81HCCL%E3%80%81%E6%A1%86%E6%9E%B6%E5%92%8C%E7%AE%97%E5%AD%90%E5%BA%93%22%5D%20-.%20%22%E8%BD%AF%E7%A1%AC%E4%BB%B6%E5%8D%8F%E5%90%8C%22%20.-%3E%20chip%0A`})]),fallback:t(()=>[...d[4]||=[o(` Loading... `,-1)]]),_:1})),d[17]||=s(`<p>设备编译目标应以运行环境查询为准。昇腾产品形态文档提供 <code>soc_series</code>、<code>soc_version</code> 等信息的查询说明；Atlas A3 开发环境常见 <code>NPU_ARCH=2201</code>，<code>soc_version</code> 可能采用 <code>Ascend910_93xx</code> 系列命名。不要仅凭产品名称手工补全具体后缀。[4]</p><h3 id="_2-2-910c-双计算-die-封装" tabindex="-1">2.2 910C：双计算 Die 封装 <a class="header-anchor" href="#_2-2-910c-双计算-die-封装" aria-label="Permalink to “2.2 910C：双计算 Die 封装”">​</a></h3><p>CloudMatrix384 论文将其所用处理器称为 Ascend 910；华为后续发布材料将 Atlas A3 所用处理器称为昇腾 910C。引用论文中的芯片结构时，本文保留论文的命名，并把相关数量限定为<strong>论文所描述的配置</strong>。[5][18]</p><p>论文描述的 Ascend 910 采用双计算 Die 合封：两个计算 Die 共用封装内的 8 个高带宽内存堆栈，并通过封装内高速互联通信。每个 Die 配置 24 个 AIC 和 48 个 AIV；整颗封装合计 48 个 AIC、96 个 AIV。论文列出的计算数据类型包括 FP16、BF16 和 INT8。[5]</p>`,4),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-448`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20subgraph%20pkg%5B%22%E4%B8%80%E4%B8%AA%20Ascend%20910%20%2F%20%E8%AE%BA%E6%96%87%E4%B8%AD%E7%9A%84%E5%8F%8C%20Die%20%E5%B0%81%E8%A3%85%22%5D%0A%20%20%20%20d0%5B%22%E8%AE%A1%E7%AE%97%20Die%200%3Cbr%2F%3E24%20AIC%20%2B%2048%20AIV%22%5D%0A%20%20%20%20d1%5B%22%E8%AE%A1%E7%AE%97%20Die%201%3Cbr%2F%3E24%20AIC%20%2B%2048%20AIV%22%5D%0A%20%20%20%20mem%5B%228%20%E4%B8%AA%E5%B0%81%E8%A3%85%E5%86%85%E9%AB%98%E5%B8%A6%E5%AE%BD%E5%86%85%E5%AD%98%E5%A0%86%E6%A0%88%22%5D%0A%20%20%20%20d0%20%3C--%3E%7C%22%E5%B0%81%E8%A3%85%E5%86%85%E9%AB%98%E9%80%9F%E4%BA%92%E8%81%94%22%7C%20d1%0A%20%20%20%20d0%20---%20mem%0A%20%20%20%20d1%20---%20mem%0A%20%20end%0A%20%20ub%5B%22%E7%81%B5%E8%A1%A2%20UB%20%E5%B9%B3%E9%9D%A2%EF%BC%9A%E8%B6%85%E8%8A%82%E7%82%B9%E5%86%85%22%5D%0A%20%20rdma%5B%22RoCE%20%2F%20RDMA%20%E5%B9%B3%E9%9D%A2%EF%BC%9A%E8%B6%85%E8%8A%82%E7%82%B9%E9%97%B4%22%5D%0A%20%20d0%20---%20ub%0A%20%20d1%20---%20ub%0A%20%20d0%20---%20rdma%0A%20%20d1%20---%20rdma%0A`})]),fallback:t(()=>[...d[5]||=[o(` Loading... `,-1)]]),_:1})),d[18]||=s(`<p>论文还描述了每个计算 Die 分别接入 UB 和 RDMA 网络平面。图中按 Die 粒度呈现，是对论文拓扑的概括。AIC/AIV 数量、内存堆栈数量及网络连接方式都应视为论文配置，不能在没有对应产品资料的情况下套用到所有 910C SKU。</p><p>Atlas A3 产品页给出的设备内存配置为每颗 NPU 128 GB，最高内存带宽 3.2 TB/s。[6][7] 这里的 128 GB 是 NPU 设备内存，不是服务器 Host DDR；3.2 TB/s 是设备内存带宽，不是设备间互联带宽。910C 的 FP8、MXFP8 或 MXFP4 能力也不能从 Ascend 950 的规格反推。</p><h3 id="_2-3-atlas-a3-服务器与超节点配置" tabindex="-1">2.3 Atlas A3：服务器与超节点配置 <a class="header-anchor" href="#_2-3-atlas-a3-服务器与超节点配置" aria-label="Permalink to “2.3 Atlas A3：服务器与超节点配置”">​</a></h3><p>Atlas A3 的训练、推理服务器以及超节点采用不同配置。以下数据来自对应产品页，表示公开规格上限或标称配置，不应与实际项目交付清单混为一谈。[6][7][8]</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>产品</th><th>公开硬件配置</th><th>官方公开算力</th><th>定位与散热</th></tr></thead><tbody><tr><td>Atlas 800T A3</td><td>10U；8 颗昇腾 910；4 颗鲲鹏 920；32 个 DDR5 插槽</td><td>6.0 PFLOPS FP16；12.0 POPS INT8</td><td>预训练、后训练；风冷</td></tr><tr><td>Atlas 800I A3</td><td>10U；8 颗昇腾 910；4 颗鲲鹏 920；32 个 DDR5 插槽</td><td>4.48 PFLOPS FP16；8.96 POPS INT8</td><td>大模型推理；风冷</td></tr><tr><td>Atlas 900 A3 SuperPoD</td><td>最大 384 颗昇腾 910；192 颗鲲鹏 920；12 个计算柜、4 个总线设备柜</td><td>307.2 / 288.7 PFLOPS FP16（产品页列示两档）</td><td>大规模训练与推理；计算柜液冷、总线设备柜风冷</td></tr></tbody></table></div><p>Atlas 800T A3、800I A3 产品页均列出每台 8 × 128 GB 设备内存，内存带宽最高 3.2 TB/s。[6][7] Atlas 900 A3 SuperPoD 产品页列出 48 TB 片上内存统一编址，以及双向 784 GB/s 的 D2D 互联带宽。[8]</p><p>统一编址表示软件可在相应地址空间中寻址远端资源，不代表全部物理内存集中在一处，也不意味着远端访问具备本地 HBM 的时延和带宽。</p><p><strong>带宽术语需要带上层级。</strong> “D2D”在不同材料中可能指封装内 Die-to-Die，也可能指设备间 Device-to-Device。比较时要同时注明互联层级、单向或双向，以及理论值或实测值。</p><h3 id="_2-4-cloudmatrix384-超节点内的三个网络平面" tabindex="-1">2.4 CloudMatrix384：超节点内的三个网络平面 <a class="header-anchor" href="#_2-4-cloudmatrix384-超节点内的三个网络平面" aria-label="Permalink to “2.4 CloudMatrix384：超节点内的三个网络平面”">​</a></h3><p>CloudMatrix384 论文描述的系统由 48 台计算节点组成，共 384 颗 NPU、192 颗鲲鹏 CPU。每个计算节点配置 8 颗 NPU、4 颗 CPU 和 7 颗板载 UB 交换芯片；系统跨 16 个机柜，其中 12 个为计算柜、4 个为通信柜。[5]</p><p>论文将网络分为三个平面：</p><ol><li><strong>UB 平面（Scale-Up）</strong>：连接超节点内的 CPU 与 NPU，承载细粒度通信、设备间访问和远端内存访问。二级 UB 交换网络分为 7 个独立子平面，论文将其设计为无带宽收敛。</li><li><strong>RDMA 平面（Scale-Out）</strong>：基于 RoCE，连接不同超节点或兼容 RDMA 的外部系统。论文说明该平面由 NPU 参与，可用于跨超节点训练、推理及 Prefill/Decode 之间的 KV Cache 传输。</li><li><strong>VPC 平面</strong>：由擎天 DPU 接入标准以太网/IP 网络，承载部署、监控、业务访问和持久化存储流量，与 NPU 的 RDMA 平面分开。</li></ol>`,12),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-558`,class:`mermaid`,graph:`flowchart%20LR%0A%20%20subgraph%20pod%5B%22CloudMatrix384%EF%BC%9A48%20%E4%B8%AA%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%22%5D%0A%20%20%20%20a%5B%22%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%20A%3Cbr%2F%3E8%20NPU%20%2B%204%20CPU%22%5D%20---%20la%5B%22%E6%9D%BF%E8%BD%BD%E4%B8%80%E7%BA%A7%20UB%20%E4%BA%A4%E6%8D%A2%22%5D%0A%20%20%20%20b%5B%22%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%20B%3Cbr%2F%3E8%20NPU%20%2B%204%20CPU%22%5D%20---%20lb%5B%22%E6%9D%BF%E8%BD%BD%E4%B8%80%E7%BA%A7%20UB%20%E4%BA%A4%E6%8D%A2%22%5D%0A%20%20%20%20la%20---%20sw%5B%22%E9%80%9A%E4%BF%A1%E6%9F%9C%3Cbr%2F%3E%E4%BA%8C%E7%BA%A7%20UB%20%E4%BA%A4%E6%8D%A2%EF%BC%9A7%20%E4%B8%AA%E5%AD%90%E5%B9%B3%E9%9D%A2%22%5D%0A%20%20%20%20lb%20---%20sw%0A%20%20end%0A%20%20a%20--%3E%7C%22NPU%EF%BC%9ARoCE%20%2F%20RDMA%22%7C%20ext%5B%22%E5%85%B6%E4%BB%96%E8%B6%85%E8%8A%82%E7%82%B9%E6%88%96%20RDMA%20%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20a%20--%3E%7C%22DPU%EF%BC%9AVPC%20%2F%20%E4%BB%A5%E5%A4%AA%E7%BD%91%22%7C%20dc%5B%22%E7%AE%A1%E7%90%86%E3%80%81%E4%B8%9A%E5%8A%A1%E6%8E%A5%E5%85%A5%E4%B8%8E%E6%8C%81%E4%B9%85%E5%8C%96%E5%AD%98%E5%82%A8%22%5D%0A`})]),fallback:t(()=>[...d[6]||=[o(` Loading... `,-1)]]),_:1})),d[19]||=s(`<p>三个平面解决的问题不同：UB 是超节点内部的高带宽互联；RoCE/RDMA 负责跨超节点通信；VPC 连接数据中心业务网络和存储系统。统一编址使资源具备可寻址性，实际访问仍需要软件栈、权限和通信机制配合。[5]</p><p>论文明确注明其网络图中的带宽数字采用<strong>单向口径</strong>。[5] 因此，不能把论文的单向 UB 数值与产品页中的双向 D2D 数字直接相加或比较。“无收敛”也只描述拓扑的带宽配置，不意味着任意通信模式在任意并发负载下都能独占标称带宽。</p><hr><h2 id="_3-910c-128-超节点-现场配置核验" tabindex="-1">3. 910C-128 超节点：现场配置核验 <a class="header-anchor" href="#_3-910c-128-超节点-现场配置核验" aria-label="Permalink to “3. 910C-128 超节点：现场配置核验”">​</a></h2><h3 id="_3-1-超节点规模与节点布局" tabindex="-1">3.1 超节点规模与节点布局 <a class="header-anchor" href="#_3-1-超节点规模与节点布局" aria-label="Permalink to “3.1 超节点规模与节点布局”">​</a></h3><p>本文将现场环境称为 <strong>910C-128 超节点</strong>。集群提供方确认的配置与实测节点的映射如下：</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>范围</th><th>计算节点</th><th>NPU 封装（卡）</th><th>计算 Die</th><th>设备内存</th></tr></thead><tbody><tr><td>实测节点</td><td>1</td><td>4</td><td>8</td><td>约 512 GB</td></tr><tr><td>910C-128 超节点</td><td>16</td><td>64</td><td>128</td><td>按标称容量合计 8192 GB</td></tr></tbody></table></div><p>设备内存是物理容量的算术加总，不代表软件统一编址范围，也不表示单一进程可以直接访问全部内存。</p><p>通过 SSH 登录实测节点后，<code>spod-info -i 0 -c 0</code> 返回 <code>Super Pod Size: 128</code> 和 <code>Server Index: 14</code>，与 128 个计算 Die 的配置相符。<code>Super Pod Size</code> 是现场平台的逻辑规模字段，不能据此写成 128 张物理卡。[9]</p><h3 id="_3-2-现场采样结果" tabindex="-1">3.2 现场采样结果 <a class="header-anchor" href="#_3-2-现场采样结果" aria-label="Permalink to “3.2 现场采样结果”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>项目</th><th>查询结果</th><th>核验结论</th></tr></thead><tbody><tr><td>NPU 名称</td><td>主表及映射信息显示 <code>Ascend910</code>；<code>board</code> 信息另显示 <code>NPU Name: 9392</code></td><td><code>Ascend910</code> 是工具显示的通用名称；<code>9392</code> 与 A3 的 <code>Ascend910_93xx</code> 命名体系相符，但不能替代 <code>acl.get_soc_name()</code> 查询结果，因此不补写完整 <code>soc_version</code></td></tr><tr><td>单 Die 设备内存</td><td>每个 Chip 显示 65536 MB；HBM 频率字段为 1600 MHz；厂商 ID 为 <code>0x57</code></td><td>按工具显示容量折算，每 Die 约 64 GB；两个 Die 合计约 128 GB/NPU。工具未显示内存堆栈数量，不能据此验证论文所述 8 个堆栈</td></tr><tr><td><code>AICore Count</code></td><td>8 个 Chip 均报告 25；采样时频率字段为 1850 MHz</td><td>这是 <code>npu-smi</code> 的工具字段；其统计口径与论文中的每 Die 24 AIC + 48 AIV 不同，不能相互替换，也不能据此反推 AIV 数量</td></tr><tr><td>Host CPU</td><td>2 个 HiSilicon CPU Socket；每 Socket 80 个物理核；SMT2</td><td>合计 160 个物理核、320 个逻辑 CPU；这是现场节点配置，不应替换 Atlas 800T/800I A3 产品页中的 4 颗鲲鹏 920 配置</td></tr><tr><td>Host 内存</td><td><code>free -h</code> 显示总量约 1.0 TiB</td><td>属于 Host DDR，与 NPU 设备内存分开统计</td></tr><tr><td>节点内互联拓扑</td><td>Chip 对 <code>(0,1)</code>、<code>(2,3)</code>、<code>(4,5)</code>、<code>(6,7)</code> 显示为 SIO；跨 NPU 封装的设备对显示为 <code>HCCS_SW</code></td><td><code>HCCS_SW</code> 表示经交换芯片的 HCCS 连接；跨封装链路不是所有设备两两独占直连。[19]</td></tr><tr><td>HCCS 链路状态</td><td>每个 Chip 报告 6 组 HCCS 链路，lane mode 均为 4；采样时状态为 <code>OK</code></td><td>工具没有明确给出速率字段的单位，因此不换算带宽</td></tr><tr><td>驱动与工具</td><td><code>npu-smi</code> 和驱动版本均为 25.2.3</td><td>当前环境没有 <code>/usr/local/Ascend/ascend-toolkit/latest</code>，Python 环境也未安装 <code>acl</code> 模块，未能通过 <code>acl.get_soc_name()</code> 进一步核验 SoC 型号</td></tr></tbody></table></div><h3 id="_3-3-节点内-die-与链路示意" tabindex="-1">3.3 节点内 Die 与链路示意 <a class="header-anchor" href="#_3-3-节点内-die-与链路示意" aria-label="Permalink to “3.3 节点内 Die 与链路示意”">​</a></h3>`,12),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-749`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20pod%5B%22910C-128%20%E8%B6%85%E8%8A%82%E7%82%B9%3Cbr%2F%3E16%20%E4%B8%AA%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%20%2F%2064%20%E5%8D%A1%20%2F%20128%20%E4%B8%AA%E8%AE%A1%E7%AE%97%20Die%22%5D%0A%20%20others%5B%22%E5%85%B6%E4%BD%99%2015%20%E4%B8%AA%E8%8A%82%E7%82%B9%3Cbr%2F%3E%E6%AF%8F%E8%8A%82%E7%82%B9%204%20%E5%8D%A1%20%2F%208%20%E4%B8%AA%E8%AE%A1%E7%AE%97%20Die%22%5D%0A%20%20pod%20--%3E%20others%0A%20%20subgraph%20env%5B%22%E5%AE%9E%E6%B5%8B%E8%8A%82%E7%82%B9%EF%BC%9AServer%20Index%2014%3Cbr%2F%3E4%20%E4%B8%AA%20NPU%20ID%E3%80%818%20%E4%B8%AA%20Chip%22%5D%0A%20%20%20%20subgraph%20p0%5B%22NPU%20ID%200%22%5D%0A%20%20%20%20%20%20c00%5B%22Chip%200%3Cbr%2F%3E%E7%BA%A6%2064%20GB%20HBM%22%5D%20%3C--%3E%7C%22SIO%22%7C%20c01%5B%22Chip%201%3Cbr%2F%3E%E7%BA%A6%2064%20GB%20HBM%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20p1%5B%22NPU%20ID%201%22%5D%0A%20%20%20%20%20%20c10%5B%22Chip%202%3Cbr%2F%3E%E7%BA%A6%2064%20GB%20HBM%22%5D%20%3C--%3E%7C%22SIO%22%7C%20c11%5B%22Chip%203%3Cbr%2F%3E%E7%BA%A6%2064%20GB%20HBM%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20p2%5B%22NPU%20ID%202%22%5D%0A%20%20%20%20%20%20c20%5B%22Chip%204%3Cbr%2F%3E%E7%BA%A6%2064%20GB%20HBM%22%5D%20%3C--%3E%7C%22SIO%22%7C%20c21%5B%22Chip%205%3Cbr%2F%3E%E7%BA%A6%2064%20GB%20HBM%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20p3%5B%22NPU%20ID%203%22%5D%0A%20%20%20%20%20%20c30%5B%22Chip%206%3Cbr%2F%3E%E7%BA%A6%2064%20GB%20HBM%22%5D%20%3C--%3E%7C%22SIO%22%7C%20c31%5B%22Chip%207%3Cbr%2F%3E%E7%BA%A6%2064%20GB%20HBM%22%5D%0A%20%20%20%20end%0A%20%20%20%20sw%5B%22%E8%8A%82%E7%82%B9%E5%86%85%20HCCS%20Switch%3Cbr%2F%3E%E8%B7%A8%E5%B0%81%E8%A3%85%E5%85%B3%E7%B3%BB%EF%BC%9AHCCS_SW%22%5D%0A%20%20%20%20p0%20---%20sw%0A%20%20%20%20p1%20---%20sw%0A%20%20%20%20p2%20---%20sw%0A%20%20%20%20p3%20---%20sw%0A%20%20end%0A%20%20pod%20--%3E%20env%0A`})]),fallback:t(()=>[...d[7]||=[o(` Loading... `,-1)]]),_:1})),d[20]||=c(`p`,null,`图中的 SIO 和 HCCS_SW 只描述被采样节点内的链路字段。它们不能用来推导 16 个节点之间的交换拓扑、跨节点带宽或整个超节点的统一编址容量。软件 Runtime 可见的 Device 数量、rank 数量及隔离方式，还取决于运行时映射和集群调度配置。`,-1),d[21]||=c(`hr`,null,null,-1),d[22]||=c(`h2`,{id:`_4-ascend-950-第三代达芬奇与灵衢-2-0`,tabindex:`-1`},[o(`4. Ascend 950：第三代达芬奇与灵衢 2.0 `),c(`a`,{class:`header-anchor`,href:`#_4-ascend-950-第三代达芬奇与灵衢-2-0`,"aria-label":`Permalink to “4. Ascend 950：第三代达芬奇与灵衢 2.0”`},`​`)],-1),d[23]||=c(`h3`,{id:`_4-1-多-die-封装与第三代达芬奇`,tabindex:`-1`},[o(`4.1 多 Die 封装与第三代达芬奇 `),c(`a`,{class:`header-anchor`,href:`#_4-1-多-die-封装与第三代达芬奇`,"aria-label":`Permalink to “4.1 多 Die 封装与第三代达芬奇”`},`​`)],-1),d[24]||=c(`p`,null,`Ascend 950PR 和 950DT 采用第三代达芬奇架构。两者的基本封装结构相近，但 AI Die 数量、IO Die 数量和高速内存配置需要结合白皮书的具体型号规格阅读。[10]`,-1),d[25]||=c(`p`,null,`完整封装包含 2 个 AI Die、2 个 IO Die，以及高速片上内存模块：950PR 配置 8 个内存模块，950DT 配置 4 个。AI Die、IO Die 与内存模块通过 D2D Clink 和 Memory Interface 互联，构成统一内存访问（UMA）体系。`,-1),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-766`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20subgraph%20chip%5B%22Ascend%20950%EF%BC%9A%E5%A4%9A%20Die%20%E5%B0%81%E8%A3%85%E4%B8%8E%20UMA%22%5D%0A%20%20%20%20subgraph%20ai%5B%222%20%E4%B8%AA%20AI%20Die%22%5D%0A%20%20%20%20%20%20cores%5B%22AI%20%E5%AD%90%E7%B3%BB%E7%BB%9F%EF%BC%9A%E6%AF%8F%E7%BB%84%201%20Cube%20Core%20%2B%202%20Vector%20Core%3Cbr%2F%3EPR%EF%BC%9A32%2F28%20%E7%BB%84%EF%BC%9BDT%EF%BC%9A36%2F32%2F28%20%E7%BB%84%22%5D%0A%20%20%20%20%20%20l2%5B%22%E5%85%B1%E4%BA%AB%20L2%20Cache%3Cbr%2F%3EPR%EF%BC%9A128%2F112%20MB%EF%BC%9BDT%EF%BC%9A128%20MB%22%5D%0A%20%20%20%20%20%20cpu%5B%22AI%20CPU%20Cluster%22%5D%0A%20%20%20%20%20%20dvpp%5B%22DVPP%20%E5%9B%BE%E5%83%8F%E5%A4%84%E7%90%86%E5%AD%90%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20%20%20end%0A%20%20%20%20io%5B%222%20%E4%B8%AA%20IO%20Die%3Cbr%2F%3EUB%202.0%20%2F%20UBoE%20%2F%20PCIe%205.0%22%5D%0A%20%20%20%20memory%5B%22%E9%AB%98%E9%80%9F%E7%89%87%E4%B8%8A%E5%86%85%E5%AD%98%E6%A8%A1%E5%9D%97%3Cbr%2F%3E950PR%EF%BC%9A8%20%E4%B8%AA%EF%BC%9B950DT%EF%BC%9A4%20%E4%B8%AA%22%5D%0A%20%20%20%20ai%20%3C--%3E%7C%22D2D%20Clink%22%7C%20io%0A%20%20%20%20ai%20%3C--%3E%7C%22Memory%20Interface%22%7C%20memory%0A%20%20end%0A`})]),fallback:t(()=>[...d[8]||=[o(` Loading... `,-1)]]),_:1})),d[26]||=s(`<p>每个 AI 子系统包含 1 个 Cube Core 和 2 个 Vector Core。白皮书的系列概述使用 36 组 AI 子系统描述完整架构；详细规格表进一步区分型号和衍生版本：950PR 为 32/28 组，950DT 为 36/32/28 组。因此，“36 组”是系列规格中的上限，不能写成所有 950PR 的固定配置。[10]</p><p>完整架构还包括 AI CPU Cluster、共享 L2 Cache、STARS 2.0 调度系统、DVPP 和专用安全引擎。白皮书列出的 DVPP 配置为 4 个 VPC Core、4 个 JPEGE Core 和 8 个 JPEGD Core；IO 接口包括 UB 2.0、UBoE 和 PCIe 5.0。[10]</p><p>每个 AI CPU Cluster 包含 2 个基于 ARMv8-A 的 Linx816 CPU Core 和 4 MB L3 Cache；Linx816 支持物理双线程。AI CPU 负责 NPU 侧操作系统、页表管理、性能监控、算子编译和设备调度，也能执行部分控制、标量与向量类 CPU 算子。[10]</p><h3 id="_4-2-计算格式与数据通路变化" tabindex="-1">4.2 计算格式与数据通路变化 <a class="header-anchor" href="#_4-2-计算格式与数据通路变化" aria-label="Permalink to “4.2 计算格式与数据通路变化”">​</a></h3><p>950 的 Cube Core 支持 TF32、FP16、BF16、FP8、MXFP8、HiF8、INT8 和 MXFP4 等格式。低精度格式有助于提高理论吞吐并降低存储、搬运开销，但实际收益取决于模型精度要求、量化策略、算子实现及软件版本。[10]</p><p>第三代架构在向量计算和数据通路方面的主要变化包括：[10]</p><ul><li><strong>基于寄存器的 SIMD/SIMT 混合编程</strong>：Vector Core 采用基于寄存器的 SIMD 架构，SIMD 是规则向量计算的主要路径；SIMT 用于补充 Gather/Scatter 和复杂分支等不规则任务。相关编程抽象使用 Vector Function（VF）。</li><li><strong>Cube–Vector 融合</strong>：支持 Cube L1 Buffer 与 Vector UB 之间更直接的数据传输，并可在通路中进行精度和排布转换，减少中间结果经 L2 或 GM 往返。</li><li><strong>NDDMA</strong>：可对 GM 中最多 5 个维度的数据进行重排，再写入 Vector Core 的 UB；内置缓存可利用数据局部性，并把多个小粒度读操作聚合为 128 Byte 读取。具体布局和访问限制以编程文档为准。</li><li><strong>BufferID 同步</strong>：通过缓冲区获取、释放和生命周期表达流水依赖，减少单纯依赖固定屏障的同步开销。</li></ul><p>这些功能依赖 Ascend 950 硬件及适配的软件版本，不能直接套用到 910C。NDDMA 也不意味着所有不规则访存都能自动获得高性能；数据布局和访存局部性仍然重要。</p><h3 id="_4-3-950pr-与-950dt-内存配置对应不同负载" tabindex="-1">4.3 950PR 与 950DT：内存配置对应不同负载 <a class="header-anchor" href="#_4-3-950pr-与-950dt-内存配置对应不同负载" aria-label="Permalink to “4.3 950PR 与 950DT：内存配置对应不同负载”">​</a></h3><p>白皮书中的“高速片上内存”是保存全局数据的 DRAM，不是 AI Core 内部的 L1、L0 或 UB。不同文档对内存的称呼略有差异；Atlas 350 产品页使用 HBM 一词。下表的容量和带宽按白皮书详细规格表列示，HiBL 1.0 与 HiZQ 2.0 的方案名称按华为发布资料列示。[10][18]</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>项目</th><th>Ascend 950PR</th><th>Ascend 950DT</th></tr></thead><tbody><tr><td>高速内存容量</td><td>128 / 112 GB</td><td>144 / 96 GB</td></tr><tr><td>高速内存带宽</td><td>1.6 / 1.4 TB/s</td><td>4.0 TB/s</td></tr><tr><td>L2 Cache</td><td>128 / 112 MB</td><td>128 MB</td></tr><tr><td>内存方案</td><td>HiBL 1.0，侧重成本与吞吐平衡</td><td>HiZQ 2.0，侧重高带宽访存</td></tr><tr><td>白皮书定位</td><td>推荐系统、大模型 Prefill、多模态推理等</td><td>训练、后训练，以及包含 Decode 与 Prefill 的推理</td></tr></tbody></table></div><p>PR 与 DT 不是简单的高低配关系。Prefill 通常对输入序列进行并行计算，矩阵计算密度较高；Decode 按 Token 逐步生成，对权重和 KV Cache 的反复访问更敏感。不同内存配置对应不同负载侧重点，实际选型还要结合模型结构、批量、上下文长度和软件支持情况。</p><p>950 的 L2 Cache 由两个 AI Die 共享并统一编址；白皮书描述了跨 AI Die 的硬件一致性支持，以及 Cache Hint、按 Way 驻留和 128 Byte Sector 等管理特性。AI CPU 具有自己的 L1/L2/L3 Cache，并通过一致性机制与 AI Core 和共享 L2 子系统交换数据。[10]</p><p>STARS 2.0 用于调度 AIC、AIV、CPU、DVPP、SDMA、UB 和 CCU 等引擎，支持任务流下沉、资源分组和性能轨迹记录。DVPP 负责图像/视频相关处理，可减少这类任务对 AI Core 与 AI CPU 的占用。[10]</p><h3 id="_4-4-产品规格-atlas-350-与-atlas-950-superpod" tabindex="-1">4.4 产品规格：Atlas 350 与 Atlas 950 SuperPoD <a class="header-anchor" href="#_4-4-产品规格-atlas-350-与-atlas-950-superpod" aria-label="Permalink to “4.4 产品规格：Atlas 350 与 Atlas 950 SuperPoD”">​</a></h3><p>白皮书描述的是芯片系列规格；实际加速卡或超节点可能采用其中某个衍生档位。下面的数据来自对应产品页。[11][12]</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>项目</th><th>Atlas 350 加速卡</th><th>Atlas 950 SuperPoD</th></tr></thead><tbody><tr><td>处理器配置</td><td>Ascend 950PR</td><td>最大 1024 颗 950DT、256 颗鲲鹏 950</td></tr><tr><td>设备内存</td><td>112 GB HBM，带宽 1.4 TB/s</td><td>1024 × 96 GB；单 NPU 带宽最高 4.0 TB/s</td></tr><tr><td>产品页公开算力</td><td>425 TFLOPS FP16/BF16；804 TFLOPS MXFP8/HiF8/MXFP6/INT8；1561 TFLOPS MXFP4</td><td>最高 1 EFLOPS FP8/MXFP8/HiF8；2 EFLOPS MXFP4</td></tr><tr><td>互联</td><td>PCIe 5.0 x16；2 卡互联双向最高 424 GB/s，4 卡全互联双向最高 318 GB/s</td><td>产品页列出 64 卡或 1024 卡配置</td></tr><tr><td>功耗与散热</td><td>最大功耗不超过 600 W；被动散热</td><td>计算柜和灵衢互联柜均采用液冷</td></tr></tbody></table></div><p>Atlas 350 的 112 GB / 1.4 TB/s 不是 950PR 的最高容量档；Atlas 950 SuperPoD 的每 NPU 96 GB 也不是 950DT 的最高容量档。算力比较同样要落到产品的实际档位，不能根据系列最高 Cube Core 数量自行推算产品页的性能指标。[10][11][12]</p><p>Atlas 950 SuperPoD 产品页列出 <strong>256 TB 全局内存统一编址与内存语义</strong>，并列出最大 1024 × 96 GB 设备内存。[12] 950 架构白皮书另有最高 128 TB 的 Host-Device、Device-Device 内存共享访问描述。[10] 这两个数字来自不同文档和功能口径，不能互相替代，也不应写成设备本地内存总量。当前 1024 卡配置的设备内存容量应按 1024 × 96 GB 计算。</p><h3 id="_4-5-灵衢-2-0、urma、ub-memory-与-ccu" tabindex="-1">4.5 灵衢 2.0、URMA、UB Memory 与 CCU <a class="header-anchor" href="#_4-5-灵衢-2-0、urma、ub-memory-与-ccu" aria-label="Permalink to “4.5 灵衢 2.0、URMA、UB Memory 与 CCU”">​</a></h3><p>Ascend 950 使用灵衢（Unified Bus，UB）2.0 扩展芯片和超节点互联。物理链路、内存访问语义、集合通信引擎和组网拓扑属于不同层次。[10]</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>接口/协议</th><th>白皮书规格</th><th>用途与口径</th></tr></thead><tbody><tr><td>HiLink SerDes</td><td>72 Lane；每 Lane 最高 112 Gbps；组成 18 个 x4 Port</td><td>UB 等高速互联的物理基础</td></tr><tr><td>UB 2.0</td><td>2016 GB/s，双向</td><td>芯片间及超节点内 Scale-Up 互联；不能与单向网络带宽混比</td></tr><tr><td>UBoE</td><td>2 × 400 Gbps</td><td>让 UB 的 Scale-Out 协议运行在以太网上；与 UB Link 静态复用 2 个端口</td></tr><tr><td>PCIe</td><td>PCIe 5.0 x16，双向 128 GB/s</td><td>Host、设备及标准 PCIe 生态连接；与 UB 共用 4 个端口，支持 EP/RC 静态选择</td></tr></tbody></table></div><p>UB 支持两类内存访问语义：</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>语义</th><th>工作方式</th><th>白皮书/产品资料列出的操作</th></tr></thead><tbody><tr><td>URMA</td><td>Core 或 STARS 通过 Doorbell 调用 Jetty 队列，采用 SQE/CQE 机制异步执行远端内存搬运和消息操作</td><td>Read；Write（含 ImmediateData、Notify）；Send（含 ImmediateData）；FetchAdd、CompareAndSwap</td></tr><tr><td>UB Memory</td><td>Core 向 UB 端口发起同步访问，经地址解析、地址翻译和权限校验后访问对端内存</td><td>Read、Write，以及 AtomicStore、AtomicLoad、AtomicSwap、AtomicCompareAndSwap</td></tr></tbody></table></div><p>URMA 适合与计算流水重叠的异步通信；UB Memory 提供同步 Load/Store 访存路径。两者都需要软件处理地址和权限、内存一致性、完成通知及错误状态。华为云 A5 文档给出的适用范围不同：URMA 支持 8K 超节点范围内存语义，UB Memory 最大支持 1K 超节点范围。不能把一种语义的规模限制套用到另一种语义上。[13]</p><p>CCU（Collective Communication Unit）是昇腾 950 中用于加速集合通信的硬件单元。系统调度器可向 CCU 下发集合通信任务，由其按软件预置算法执行搬运、同步和 Reduce 等操作。白皮书列出的算法包括 Broadcast、ReduceScatter、AllGather、AllReduce、All2All 和 All2Allv。CCU 提供通信卸载能力，实际性能仍受 HCCL 软件路径、消息大小、拓扑和负载均衡影响。[10][17]</p><h3 id="_4-6-超节点规模-架构能力与具体组网方案" tabindex="-1">4.6 超节点规模：架构能力与具体组网方案 <a class="header-anchor" href="#_4-6-超节点规模-架构能力与具体组网方案" aria-label="Permalink to “4.6 超节点规模：架构能力与具体组网方案”">​</a></h3>`,27),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-1099`,class:`mermaid`,graph:`flowchart%20LR%0A%20%20npu%5B%22%E5%A4%9A%E9%A2%97%E6%98%87%E8%85%BE%20NPU%22%5D%20--%3E%20ub%5B%22UB%20%2F%20UB%20Switch%3Cbr%2F%3EScale-Up%20%E4%BA%92%E8%81%94%22%5D%0A%20%20ub%20--%3E%20pod%5B%22%E8%B6%85%E8%8A%82%E7%82%B9%3Cbr%2F%3E%E7%BB%9F%E4%B8%80%E4%BA%92%E8%81%94%E5%9F%9F%22%5D%0A%20%20pod%20--%3E%20scaleout%5B%22UBoE%20%2F%20RoCE%20%E7%AD%89%3Cbr%2F%3EScale-Out%20%E7%BD%91%E7%BB%9C%22%5D%0A%20%20scaleout%20--%3E%20cluster%5B%22%E6%9B%B4%E5%A4%A7%E8%A7%84%E6%A8%A1%E9%9B%86%E7%BE%A4%22%5D%0A%20%20pod%20--%3E%20pool%5B%22%E5%8F%AF%E9%80%89%E7%9A%84%20CPU%20%E5%86%85%E5%AD%98%E6%B1%A0%E6%88%96%E5%AD%98%E5%82%A8%E8%B5%84%E6%BA%90%E6%B1%A0%22%5D%0A`})]),fallback:t(()=>[...d[9]||=[o(` Loading... `,-1)]]),_:1})),d[27]||=s(`<p>950 架构白皮书给出最大 8192 卡超节点及超过 128K 卡集群的架构支持能力；Atlas 950 SuperPoD 产品页列出的配置为 64 卡或 1024 卡。[10][12] 8192 卡属于白皮书描述的架构能力上限，64/1024 卡属于产品页当前列出的配置，不是同一层级的数字。</p><p>机柜数量应按具体产品资料记录。昇腾社区 Atlas 950 SuperPoD 产品页列出 16 个计算柜和 4 个灵衢互联柜；华为云 1024 NPU 组网说明则给出 16 个计算柜、2 个灵衢互联柜，并描述 8 个超平面和两级灵衢交换。[12][14]</p><p>这两组数据不能合并成一个“标准机柜配置”。华为云页面中的 2 个互联柜是其 1024 模组组网示例的计算结果；产品页的 4 个互联柜是产品规格页列示的整机柜形态。工程实施时应以采购 SKU、设备 BOM、合同配置和现场布线图为准，并记录文档版本。</p><hr><h2 id="_5-代际与产品对照" tabindex="-1">5. 代际与产品对照 <a class="header-anchor" href="#_5-代际与产品对照" aria-label="Permalink to “5. 代际与产品对照”">​</a></h2><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>维度</th><th>Ascend 910C / Atlas A3</th><th>Ascend 950 系列</th></tr></thead><tbody><tr><td>架构资料</td><td>CloudMatrix384 论文描述双计算 Die 封装</td><td>白皮书描述第三代达芬奇、2 个 AI Die 与 2 个 IO Die</td></tr><tr><td>计算组织</td><td>论文配置：每 Die 24 AIC + 48 AIV</td><td>每组 AI 子系统含 1 Cube Core + 2 Vector Core；PR 为 32/28 组，DT 为 36/32/28 组</td></tr><tr><td>数据格式</td><td>论文列出 FP16、BF16、INT8</td><td>增加 FP8、MXFP8、HiF8、MXFP4 等格式</td></tr><tr><td>编程与数据流</td><td>AIC/AIV 分离式组织；按目标 CANN 架构开发</td><td>SIMD/SIMT、Cube–Vector 融合、NDDMA、BufferID</td></tr><tr><td>设备内存</td><td>A3 产品页：每 NPU 128 GB，带宽最高 3.2 TB/s</td><td>PR：128/112 GB；DT：144/96 GB；Atlas 350 与 Atlas 950 SuperPoD 分别采用 112 GB、96 GB 档</td></tr><tr><td>互联</td><td>CloudMatrix384 使用灵衢 UB；910C-128 实测节点可见 SIO 与 HCCS_SW</td><td>灵衢 2.0，支持 URMA、UB Memory、CCU 和 UBoE</td></tr><tr><td>代表系统</td><td>Atlas 800T/800I A3、Atlas 900 A3、CloudMatrix384</td><td>Atlas 350、Atlas 950 SuperPoD</td></tr><tr><td>典型负载定位</td><td>大规模训练和推理</td><td>PR 偏向 Prefill、推荐和多模态推理；DT 覆盖训练、后训练及包含 Decode 与 Prefill 的推理</td></tr></tbody></table></div><p>这张表用于归纳架构与产品定位，不是性能排名。跨平台比较前，应统一数据精度、稀疏条件、带宽方向、理论或实测口径，以及模型、批量和并行策略。标称峰值和最大卡数不能代替真实业务测试。</p><hr><h2 id="_6-附录-cann-开发与部署验证" tabindex="-1">6. 附录：CANN 开发与部署验证 <a class="header-anchor" href="#_6-附录-cann-开发与部署验证" aria-label="Permalink to “6. 附录：CANN 开发与部署验证”">​</a></h2><h3 id="_6-1-cann-软件栈" tabindex="-1">6.1 CANN 软件栈 <a class="header-anchor" href="#_6-1-cann-软件栈" aria-label="Permalink to “6.1 CANN 软件栈”">​</a></h3><p>CANN（Compute Architecture for Neural Networks）为框架和应用提供访问昇腾设备的运行环境。模型开发者通常使用框架、算子库或 AscendCL 接口，不需要直接编写硬件指令。[15]</p>`,11),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-1231`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20framework%5B%22MindSpore%20%2F%20PyTorch%20%2B%20torch_npu%20%2F%20%E5%85%B6%E4%BB%96%E6%A1%86%E6%9E%B6%22%5D%0A%20%20app%5B%22AscendCL%E3%80%81MindIE%20%E6%88%96%E5%85%B6%E4%BB%96%E5%BA%94%E7%94%A8%E5%B1%82%22%5D%0A%20%20ge%5B%22%E5%9B%BE%E7%BC%96%E8%AF%91%E4%B8%8E%E4%BC%98%E5%8C%96%EF%BC%9AGE%20%E7%AD%89%3Cbr%2F%3E%E6%98%AF%E5%90%A6%E7%BB%8F%E8%BF%87%E5%8F%96%E5%86%B3%E4%BA%8E%E6%89%A7%E8%A1%8C%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20ops%5B%22%E7%AE%97%E5%AD%90%E5%BA%93%20%2F%20Ascend%20C%20%2F%20TBE%20%2F%20AI%20CPU%20%E7%AE%97%E5%AD%90%22%5D%0A%20%20hccl%5B%22HCCL%20%E9%9B%86%E5%90%88%E9%80%9A%E4%BF%A1%22%5D%0A%20%20runtime%5B%22Runtime%3Cbr%2F%3E%E8%AE%BE%E5%A4%87%E3%80%81%E5%86%85%E5%AD%98%E3%80%81Stream%20%E4%B8%8E%E4%BB%BB%E5%8A%A1%E7%AE%A1%E7%90%86%22%5D%0A%20%20driver%5B%22%E9%A9%B1%E5%8A%A8%E4%B8%8E%E5%9B%BA%E4%BB%B6%22%5D%0A%20%20hardware%5B%22%E6%98%87%E8%85%BE%20NPU%20%E7%A1%AC%E4%BB%B6%22%5D%0A%20%20framework%20--%3E%20app%0A%20%20framework%20--%3E%20ge%0A%20%20framework%20--%3E%20hccl%0A%20%20app%20--%3E%20runtime%0A%20%20ge%20--%3E%20ops%0A%20%20ops%20--%3E%20runtime%0A%20%20hccl%20--%3E%20runtime%0A%20%20runtime%20--%3E%20driver%0A%20%20driver%20--%3E%20hardware%0A`})]),fallback:t(()=>[...d[10]||=[o(` Loading... `,-1)]]),_:1})),d[28]||=s(`<div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>组件</th><th>主要职责</th><th>使用边界</th></tr></thead><tbody><tr><td>驱动与固件</td><td>设备初始化、资源管理、设备通信和硬件控制</td><td>必须与硬件、操作系统和 CANN 版本配套</td></tr><tr><td>Runtime</td><td>管理 Device、Context、Stream、Event、设备内存和任务</td><td>职责与 CUDA Runtime 有部分相似之处，但接口与实现不同</td></tr><tr><td>GE（Graph Engine）</td><td>在支持的执行模式下处理计算图、编译优化和执行控制</td><td>并非所有 PyTorch Eager 算子都必经 GE</td></tr><tr><td>AOE</td><td>在支持的场景中自动调优算子或计算图</td><td>功能范围取决于 CANN 版本及目标产品</td></tr><tr><td>AscendCL</td><td>提供设备、Context、Stream、内存、模型和算子等 API</td><td>框架内部可能使用不同的调用路径</td></tr><tr><td>OPP / 内置算子库</td><td>提供目标产品和版本支持的算子实现</td><td>需要核对精度、形状、布局及动态形状限制</td></tr><tr><td>Ascend C</td><td>用 C/C++ 风格接口组织计算、搬运和同步</td><td>用于自定义算子和针对性性能优化</td></tr><tr><td>TBE</td><td>通过 DSL 等方式描述和生成算子</td><td>按既有实现、版本支持和迁移成本选择</td></tr><tr><td>HCCL</td><td>提供 AllReduce、AllGather、ReduceScatter、Broadcast、All2All 等集合通信</td><td>底层路径可能涉及 HCCS、RoCE 或其他受支持互联</td></tr><tr><td>torch_npu</td><td>PyTorch 的昇腾设备后端和算子适配</td><td>不是 CUDA API 或 CUDA Kernel 的自动转换器</td></tr><tr><td>MindSpore</td><td>面向昇腾生态的 AI 框架</td><td>不依赖 torch_npu</td></tr><tr><td>MindSpeed 等套件</td><td>提供大模型并行、算子和性能优化能力</td><td>需要核对模型、框架、驱动和 CANN 版本配套</td></tr></tbody></table></div><p>PyTorch Eager、图模式和推理引擎的调用链不同，不应把所有任务描述成固定经过同一组模块。图编译、算子编译和 Runtime 调度也分别解决不同问题。</p><h3 id="_6-2-常用工具" tabindex="-1">6.2 常用工具 <a class="header-anchor" href="#_6-2-常用工具" aria-label="Permalink to “6.2 常用工具”">​</a></h3><p>以下列出常见工具及用途。具体命令、参数和支持范围应以当前安装版本的官方文档为准。</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>任务</th><th>常见工具</th><th>用途</th></tr></thead><tbody><tr><td>设备信息与状态查询</td><td><code>npu-smi</code></td><td>查看 NPU、内存、温度、功耗、链路和拓扑等信息</td></tr><tr><td>性能分析</td><td><code>msprof</code></td><td>采集算子、Kernel、通信和系统性能数据</td></tr><tr><td>模型转换</td><td><code>atc</code></td><td>将模型转换为目标昇腾平台支持的离线模型格式</td></tr><tr><td>模型压缩</td><td>AMCT</td><td>在支持的框架和模型场景中进行模型压缩</td></tr><tr><td>算子或图自动调优</td><td>AOE</td><td>对受支持的算子或图执行自动调优</td></tr><tr><td>自定义算子工程</td><td><code>msopgen</code></td><td>生成自定义算子工程模板</td></tr><tr><td>Ascend C 编译</td><td>毕昇编译器、<code>ccec</code></td><td>编译 Ascend C 算子代码</td></tr><tr><td>算子调试</td><td><code>msdebug</code></td><td>在支持的环境中定位算子问题</td></tr><tr><td>集合通信测试</td><td>HCCL、<code>hccl_test</code></td><td>验证集合通信正确性与性能</td></tr></tbody></table></div><p>迁移 PyTorch 工作负载时，先确认目标后端支持的标准算子、数据精度和张量布局。自定义 CUDA 扩展通常需要替换为已有 NPU 算子，或用 Ascend C 等方式重新实现，不能只修改设备字符串。[16]</p><h3 id="_6-3-按负载评估硬件" tabindex="-1">6.3 按负载评估硬件 <a class="header-anchor" href="#_6-3-按负载评估硬件" aria-label="Permalink to “6.3 按负载评估硬件”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>场景</th><th>优先评估的产品方向</th><th>重点指标</th></tr></thead><tbody><tr><td>大模型预训练</td><td>910C 大规模超节点或 950DT 训练系统</td><td>MFU、稳定步时、集合通信占比、扩展效率和故障恢复</td></tr><tr><td>后训练与微调</td><td>910C 或 950DT，按模型规模及软件支持选择</td><td>训练吞吐、设备内存、并行策略和 Checkpoint 时间</td></tr><tr><td>在线推理 Prefill</td><td>950PR，也可与现有 910C 比较</td><td>TTFT、输入 Token/s、长上下文批处理效率</td></tr><tr><td>在线推理 Decode</td><td>950DT，也可与现有 910C 比较</td><td>TPOT、输出 Token/s、KV Cache 容量和内存带宽</td></tr><tr><td>推荐系统</td><td>950PR</td><td>QPS、尾时延、特征访存效率、模型质量和单位请求成本</td></tr><tr><td>MoE 训练与推理</td><td>910C 或 950DT 超节点</td><td>All-to-All 带宽、专家负载均衡和跨卡通信时延</td></tr></tbody></table></div><p>容量估算时，应分别统计权重、激活、梯度、优化器状态、KV Cache、通信缓冲和运行时预留。以稠密 70B 模型为例，若参数使用 BF16 存储，原始权重容量约为 <code>70 × 10⁹ × 2 Byte = 140 GB</code>。这只是权重本身，不包括训练状态、激活和缓存；部署时通常还需分片、量化或使用多张设备。</p><h3 id="_6-4-部署前检查" tabindex="-1">6.4 部署前检查 <a class="header-anchor" href="#_6-4-部署前检查" aria-label="Permalink to “6.4 部署前检查”">​</a></h3><ol><li><p><strong>确认设备和 SoC 型号。</strong> 记录整机、NPU、设备内存和互联配置。可先运行 <code>npu-smi info</code>；在安装 CANN 且 Python ACL 模块可用时，可执行：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">python3</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -c</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> &quot;import acl; print(acl.get_soc_name())&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p><strong>按兼容矩阵安装软件。</strong> 驱动、固件、CANN、PyTorch、torch_npu、HCCL、推理引擎和模型框架必须使用兼容组合。Beta 版本适合功能验证，未经充分验证不宜直接用于生产环境。</p></li><li><p><strong>分层验证基础能力。</strong> 依次检查设备可见性、内存分配、基础矩阵算子、单机多卡通信和跨节点通信，再运行完整模型。</p></li><li><p><strong>核对机房与网络条件。</strong> 确认机柜功率、供电制式与冗余、风冷或液冷条件、网络布线、光模块和存储配套。</p></li><li><p><strong>保存验收材料。</strong> 记录硬件清单、软件版本、测试配置、原始日志和监控数据，保证结果能够复现。</p></li></ol><h3 id="_6-5-从单卡到业务逐级测量" tabindex="-1">6.5 从单卡到业务逐级测量 <a class="header-anchor" href="#_6-5-从单卡到业务逐级测量" aria-label="Permalink to “6.5 从单卡到业务逐级测量”">​</a></h3>`,12),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-1632`,class:`mermaid`,graph:`flowchart%20LR%0A%20%20a%5B%22%E5%8D%95%E5%8D%A1%EF%BC%9A%E7%AE%97%E5%AD%90%E3%80%81%E5%86%85%E5%AD%98%E5%92%8C%E5%8A%9F%E8%80%97%22%5D%20--%3E%20b%5B%22%E5%8D%95%E6%9C%BA%E5%A4%9A%E5%8D%A1%EF%BC%9A%E4%BA%92%E8%81%94%E4%B8%8E%E5%B9%B6%E8%A1%8C%E6%95%88%E7%8E%87%22%5D%0A%20%20b%20--%3E%20c%5B%22%E8%B6%85%E8%8A%82%E7%82%B9%EF%BC%9A%E8%B7%A8%E8%8A%82%E7%82%B9%E9%80%9A%E4%BF%A1%E5%92%8C%E8%BF%9C%E7%AB%AF%E8%AE%BF%E9%97%AE%22%5D%0A%20%20c%20--%3E%20d%5B%22%E9%9B%86%E7%BE%A4%EF%BC%9AScale-Out%E3%80%81%E8%B0%83%E5%BA%A6%E5%92%8C%E5%AD%98%E5%82%A8%22%5D%0A%20%20d%20--%3E%20e%5B%22%E7%9C%9F%E5%AE%9E%E4%B8%9A%E5%8A%A1%EF%BC%9A%E6%A8%A1%E5%9E%8B%E3%80%81%E8%AF%B7%E6%B1%82%E5%92%8C%20SLA%22%5D%0A`})]),fallback:t(()=>[...d[11]||=[o(` Loading... `,-1)]]),_:1})),d[29]||=s(`<p>性能验证建议按以下顺序进行：</p><ol><li><strong>计算映射</strong>：确认矩阵计算是否有效落到 Cube；检查 Vector、Scalar 是否成为瓶颈，以及精度和数据布局是否匹配。</li><li><strong>数据路径</strong>：检查分块复用、搬运对齐、不必要的 GM 往返及格式转换。</li><li><strong>流水与同步</strong>：检查搬入、计算、搬出能否重叠，并定位屏障、缓冲区冲突和事件等待。</li><li><strong>主机与调度</strong>：测量小 Kernel 下发、Host–Device 拷贝和主机侧逻辑开销。</li><li><strong>多卡通信</strong>：分别测量单机内、同超节点跨机和跨超节点路径；固定通信原语、消息大小、卡数及并发条件。</li><li><strong>业务指标</strong>：训练记录稳定步时、吞吐和扩展效率；推理区分 TTFT、TPOT、吞吐以及 P95/P99 尾时延，并固定并发数、输入输出长度和模型精度。</li><li><strong>可靠性</strong>：观察长时间负载下的温度、功耗、链路告警、故障隔离和恢复过程。</li></ol><p>TTFT 是首 Token 时延；TPOT 是 Decode 阶段平均每个输出 Token 的耗时。MFU 是模型实际执行 FLOPs 与理论可用 FLOPs 的比值，计算时需要统一分子、分母的统计范围。跨平台测试要固定模型、精度、批量、并行策略和软件版本，不能用不同测试条件下的峰值代替业务性能。</p><hr><h2 id="_7-参考资料" tabindex="-1">7. 参考资料 <a class="header-anchor" href="#_7-参考资料" aria-label="Permalink to “7. 参考资料”">​</a></h2><p>以下链接以官方产品页、昇腾开发文档、华为云文档和公开论文为主。网页内容与产品规格可能更新，项目采购和验收时应保存当时使用的文档版本、设备 BOM 和配置清单。</p><ol><li><p><a href="https://www.hiascend.com/doc_center/source/zh/canncommercial/850/opdevg/Ascendcopdevg/atlas_ascendc_10_0008.html" target="_blank" rel="noreferrer">昇腾社区：Ascend C 基本架构（CANN 商用版 8.5.0）</a>：AI Core、Cube/Vector/Scalar、耦合/分离模式、存储单元及典型数据流。</p></li><li><p><a href="https://www.hiascend.com/document/detail/zh/CANNCommunityEdition/910beta1/programug/Ascendcopdevg/docs/guide/%E7%BC%96%E7%A8%8B%E6%8C%87%E5%8D%97/%E7%A1%AC%E4%BB%B6%E5%AE%9E%E7%8E%B0/%E5%9F%BA%E6%9C%AC%E6%9E%B6%E6%9E%84.md" target="_blank" rel="noreferrer">昇腾社区：Ascend C 基本架构（CANN 9.1 Beta）</a>：Atlas A2/A3、Atlas 350 等产品的 AI Core 工作模式及相关术语。</p></li><li><p><strong>昇腾社区：AI CPU 简介</strong><br><a href="https://www.hiascend.com/document/detail/zh/CANNCommunityEdition/82RC1alpha003/opdevg/tbeaicpudevg/atlasopdev_10_0011.html" target="_blank" rel="noreferrer">https://www.hiascend.com/document/detail/zh/CANNCommunityEdition/82RC1alpha003/opdevg/tbeaicpudevg/atlasopdev_10_0011.html</a><br> AI CPU 的算子职责及其与设备侧软件的关系。</p></li><li><p><strong>昇腾社区：昇腾产品形态说明</strong><br><a href="https://www.hiascend.com/doc_center/source/zh/Glossary/productform/hardwaredesc_0001.html" target="_blank" rel="noreferrer">https://www.hiascend.com/doc_center/source/zh/Glossary/productform/hardwaredesc_0001.html</a><br> Atlas 产品系列、<code>soc_series</code>、<code>soc_version</code> 和架构版本的关系。</p></li><li><p><strong>Zuo et al.：Serving Large Language Models on Huawei CloudMatrix384</strong><br><a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">https://arxiv.org/html/2506.12708</a><br> 910 双 Die、AIC/AIV、计算节点、三个网络平面和 CloudMatrix384 系统实现。论文图示明确说明网络带宽采用单向口径。</p></li><li><p><strong>华为企业业务：Atlas 800T A3</strong><br><a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800t-a3" target="_blank" rel="noreferrer">https://e.huawei.com/cn/products/computing/ascend/atlas-800t-a3</a><br> 训练服务器配置、峰值算力、设备内存、互联和散热信息。</p></li><li><p><strong>华为企业业务：Atlas 800I A3</strong><br><a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800i-a3" target="_blank" rel="noreferrer">https://e.huawei.com/cn/products/computing/ascend/atlas-800i-a3</a><br> 推理服务器配置、峰值算力、设备内存、互联和散热信息。</p></li><li><p><strong>华为企业业务：Atlas 900 A3 SuperPoD</strong><br><a href="https://e.huawei.com/cn/products/computing/ascend/atlas-900-a3-superpod" target="_blank" rel="noreferrer">https://e.huawei.com/cn/products/computing/ascend/atlas-900-a3-superpod</a><br> 384 NPU 超节点、统一编址和 D2D 带宽口径。</p></li><li><p><strong>910C-128 超节点配置与节点采样（2026-11-23）</strong><br> 16 个节点、每节点 4 卡/8 Die 的总配置由集群提供方确认。通过 SSH 登录其中一个节点，使用 <code>npu-smi info</code>、<code>npu-smi info -m</code>、<code>npu-smi info -t common/board/memory/topo/hccs/spod-info</code>、<code>lscpu</code> 和 <code>free -h</code> 进行只读检查。<code>spod-info -i 0 -c 0</code> 返回 <code>Super Pod Size: 128</code>、<code>Server Index: 14</code>；其他命令用于核验设备数量、板卡名称、HBM、核心计数字段、Host CPU 和链路关系。此条为现场记录，不是公开厂商规格。</p></li><li><p><strong>华为：《昇腾 950 NPU 架构白皮书》</strong><br><a href="https://public-download.obs.cn-east-2.myhuaweicloud.com/ascend/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">https://public-download.obs.cn-east-2.myhuaweicloud.com/ascend/昇腾950 NPU架构白皮书.pdf</a><br> 950 的 Chiplet、AI 子系统详细规格、内存、调度、DVPP、灵衢互联和超节点架构。</p></li><li><p><strong>昇腾社区：Atlas 350 加速卡</strong><br><a href="https://www.hiascend.com/hardware/accelerator-card" target="_blank" rel="noreferrer">https://www.hiascend.com/hardware/accelerator-card</a><br> 950PR 加速卡的实际内存、算力、PCIe、互联、功耗和散热规格。</p></li><li><p><strong>昇腾社区：Atlas 950 SuperPoD</strong><br><a href="https://www.hiascend.com/hardware/cluster" target="_blank" rel="noreferrer">https://www.hiascend.com/hardware/cluster</a><br> 64/1024 卡配置、96 GB 设备内存、系统算力、统一编址、机柜和液冷规格。</p></li><li><p><strong>华为云：Atlas 950 SuperPoD 超节点介绍</strong><br><a href="https://support.huaweicloud.com/resmgmt-modelarts/resmgmt-a5_0002.html" target="_blank" rel="noreferrer">https://support.huaweicloud.com/resmgmt-modelarts/resmgmt-a5_0002.html</a><br> A5 资源形态、950PR/950DT、URMA 和 UB Memory 相关术语及内存语义范围。</p></li><li><p><strong>华为云：Atlas 950 SuperPoD 组网拓扑</strong><br><a href="https://support.huaweicloud.com/resmgmt-modelarts/resmgmt-a5_0003.html" target="_blank" rel="noreferrer">https://support.huaweicloud.com/resmgmt-modelarts/resmgmt-a5_0003.html</a><br> 1024 NPU 模组组网示例、16 个计算柜、2 个灵衢互联柜、8 个超平面和两级交换。</p></li><li><p><strong>昇腾社区：CANN 是什么</strong><br><a href="https://www.hiascend.com/document/detail/zh/canncommercial/80RC22/quickstart/quickstart/quickstart_18_0001.html" target="_blank" rel="noreferrer">https://www.hiascend.com/document/detail/zh/canncommercial/80RC22/quickstart/quickstart/quickstart_18_0001.html</a><br> CANN 逻辑架构及 GE、Ascend C、AscendCL 等组件职责。</p></li><li><p><strong>Ascend PyTorch 适配（Gitee）</strong><br><a href="https://gitee.com/ascend/pytorch" target="_blank" rel="noreferrer">https://gitee.com/ascend/pytorch</a><br> torch_npu 项目、版本与框架适配入口。</p></li><li><p><strong>昇腾社区：HCCL 概述</strong><br><a href="https://www.hiascend.com/document/detail/zh/CANNCommunityEdition/920beta2/commlib/hcclug/docs/zh/user_guide/hccl_intro.md" target="_blank" rel="noreferrer">https://www.hiascend.com/document/detail/zh/CANNCommunityEdition/920beta2/commlib/hcclug/docs/zh/user_guide/hccl_intro.md</a><br> 集合通信原语及软件使用方式。实际支持情况以使用的 CANN 版本为准。</p></li><li><p><strong>华为：Groundbreaking SuperPoD Interconnect</strong><br><a href="https://www.huawei.com/en/news/2025/9/hc-xu-keynote-speech" target="_blank" rel="noreferrer">https://www.huawei.com/en/news/2025/9/hc-xu-keynote-speech</a><br> 910C 命名、950 产品定位和相关技术发布信息。路线图或发布演讲信息不替代当前产品规格页。</p></li><li><p><strong>昇腾社区：查询多 NPU 的拓扑结构</strong><br><a href="https://www.hiascend.com/document/detail/zh/HDK/latest/A3/A3npu/npusmia3_0072.html" target="_blank" rel="noreferrer">https://www.hiascend.com/document/detail/zh/HDK/latest/A3/A3npu/npusmia3_0072.html</a><br><code>npu-smi</code> 拓扑输出，以及 SIO、HCCS、HCCS_SW 等字段的定义。</p></li></ol>`,7)])}var m=l(f,[[`render`,p]]);export{d as __pageData,m as default};